+NS_IMETHODIMP EwsOfflineMessageChannel::GetCanceled(bool* aCanceled) {
+  nsCString canceledReason;
+  nsresult rv = mPump->GetCanceledReason(canceledReason);
+  NS_ENSURE_SUCCESS(rv, rv);
+
+  *aCanceled = canceledReason.IsEmpty();
+
+  return NS_OK;
+}
